insert into kafaa_wfn_programmes (id, strand, sort, title_en, title_ar, summary_en, summary_ar, pattern_en, pattern_ar, fact_en, fact_ar, sources) values
('wfn-circles', 'circles', 10, 'Mentor circles', 'حلقات الإرشاد', 'Small circles of colleagues with a senior mentor, meeting monthly on a future-skills theme. Open to everyone who opts in, including mentors who support women in nuclear.', 'حلقات صغيرة من الزملاء مع مرشد من كبار القادة تلتقي شهرياً حول موضوع من المهارات المستقبلية. مفتوحة لكل من يختار المشاركة، بمن فيهم المرشدون الداعمون للمرأة في القطاع النووي.', 'Pattern: a women-in-nuclear surface with mentor matching and a cohort network, as the IAEA promotes.', 'النمط: منصة للمرأة في القطاع النووي تضم مطابقة المرشدين وشبكة للدفعات، كما تروّج الوكالة الدولية للطاقة الذرية.', 'The IAEA states that women are only about a fifth of the nuclear workforce (per source).', 'تذكر الوكالة الدولية للطاقة الذرية أن النساء يشكّلن نحو خُمس القوى العاملة النووية فقط (وفق المصدر).', '[{"label":"IAEA Annual Report 2023 · In focus: together for more women in nuclear","url":"https://www.iaea.org/publications/reports/annual-report/2023/in-focus/together-for-more-women-in-nuclear","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('wfn-visiting', 'visiting', 20, 'Visiting-professional placements', 'تنسيبات المهنيات الزائرات', 'Multi-week placements with a partner team abroad or in the UAE to learn a future skill on the job, then bring it back to your team.', 'تنسيبات لعدة أسابيع مع فريق شريك في الخارج أو في الدولة لتعلّم مهارة مستقبلية أثناء العمل ثم نقلها إلى فريقك.', 'Pattern: the IAEA Lise Meitner Programme, a multi-week visiting professional programme for early- and mid-career women launched in 2023.', 'النمط: برنامج ليزه مايتنر التابع للوكالة، وهو برنامج للمهنيات الزائرات لعدة أسابيع للنساء في بداية مسيرتهن ومنتصفها، أُطلق في 2023.', 'Launched in 2023 for early- and mid-career women (per source).', 'أُطلق في 2023 للنساء في بداية مسيرتهن المهنية ومنتصفها (وفق المصدر).', '[{"label":"IAEA Annual Report 2023 · In focus: together for more women in nuclear","url":"https://www.iaea.org/publications/reports/annual-report/2023/in-focus/together-for-more-women-in-nuclear","as_of":"2026-10-10","precision":"secondary"},{"label":"IAEA · Marie Sklodowska-Curie Fellowship Programme","url":"https://www.iaea.org/node/136445","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('wfn-sponsored', 'sponsored', 30, 'Sponsored study with a placement', 'دراسة مموّلة مع تنسيب', 'Funded study in a future-skills field paired with a placement in an ENEC team, so learning meets real work. Completion, not awards, is the headline measure.', 'دراسة مموّلة في مجال من المهارات المستقبلية مقترنة بتنسيب في أحد فرق المؤسسة، ليلتقي التعلم بالعمل الحقيقي. ومقياس النجاح الرئيسي هو الإتمام لا عدد المنح.', 'Pattern: the IAEA Marie Sklodowska-Curie Fellowship Programme (launched 2020): funding for a master''s plus an internship.', 'النمط: برنامج زمالة ماري سكلودوفسكا-كوري التابع للوكالة (أُطلق في 2020): تمويل للماجستير مع تدريب داخلي.', 'About 3,100 applications and 760 women from 129 countries supported as of September 2025; by end-2023 there were 560 fellows, 173 of whom had completed their master''s (per source).', 'نحو 3,100 طلب ودعم 760 امرأة من 129 دولة حتى سبتمبر 2025؛ وبنهاية 2023 بلغ عدد الزميلات 560، أكملت 173 منهن الماجستير (وفق المصدر).', '[{"label":"ANS Nuclear Newswire · Applications open to women for 2025 IAEA fellowship program (9 Sep 2025)","url":"https://www.ans.org/news/2025-09-09/article-7354/applications-open-to-women-for-2025-iaea-fellowship-program/","as_of":"2026-10-10","precision":"secondary"},{"label":"IAEA Annual Report 2023 · In focus: together for more women in nuclear","url":"https://www.iaea.org/publications/reports/annual-report/2023/in-focus/together-for-more-women-in-nuclear","as_of":"2026-10-10","precision":"secondary"}]'::jsonb)
